def backfill_join_codes(apps, schema_editor):
    """Give every existing society a working invite link from its slug.

    Slugs are unique but up to 80 long, so the 50-character code can collide.
    """
    Cooperative = apps.get_model("tenants", "Cooperative")
    used = set()
    for coop in Cooperative.objects.filter(join_code__isnull=True):
        base = coop.slug[:50].lower()
        code, n = base, 1
        while code in used:
            n += 1
            code = f"{base[:46]}-{n}"
        used.add(code)
        coop.join_code = code
        coop.save(update_fields=["join_code"])


